contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, address to, uint256 allowanceAmount, uint256 transferAmount) public {
        require(spender != address(0));
        require(to != address(0));
        require(spender != address(this));

        bool approveOk = c.approve(spender, allowanceAmount);
        uint256 allowanceAfterApprove = c.allowance(address(this), spender);
        uint256 ownerBalBefore = c.balanceOf(address(this));
        uint256 toBalBefore = c.balanceOf(to);

        uint256 safeTransferAmount = transferAmount;
        if (ownerBalBefore < safeTransferAmount) {
            safeTransferAmount = ownerBalBefore;
        }
        if (allowanceAfterApprove < safeTransferAmount) {
            safeTransferAmount = allowanceAfterApprove;
        }

        bool transferReverted;
        try c.transferFrom(address(this), to, safeTransferAmount) returns (bool) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        uint256 allowanceAfter = c.allowance(address(this), spender);
        uint256 ownerBalAfter = c.balanceOf(address(this));
        uint256 toBalAfter = c.balanceOf(to);

        assert(approveOk
            && allowanceAfterApprove == allowanceAmount
            && !transferReverted
            && ownerBalAfter == ownerBalBefore - safeTransferAmount
            && toBalAfter == toBalBefore + safeTransferAmount
            && allowanceAfter == allowanceAfterApprove - safeTransferAmount
            && ownerBalAfter + toBalAfter == ownerBalBefore + toBalBefore);
    }

    receive() external payable {}
}

